"use client";

import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import { createClient } from "@/lib/supabase-browser";
import { useEffect, useState, useMemo, useRef } from "react";
import { ConfirmDialog } from "@/components/ui/confirm-dialog";
import { useFinanceData } from "@/hooks/use-finance-data";
import { useUser } from "@/context/user-context";
import { getCanonicalEnabledModules } from "@/lib/modules";
import type { ModuleKey } from "@/lib/modules";

const nav = [
  {
    label: "Dashboard",
    href: "/dashboard",
    icon: (
      <svg className="w-[18px] h-[18px]" fill="none" stroke="currentColor" strokeWidth={1.8} viewBox="0 0 24 24">
        <rect x="3" y="3" width="7" height="7" rx="2" />
        <rect x="14" y="3" width="7" height="7" rx="2" />
        <rect x="3" y="14" width="7" height="7" rx="2" />
        <rect x="14" y="14" width="7" height="7" rx="2" />
      </svg>
    ),
  },
  {
    label: "Accounts",
    href: "/dashboard/accounts",
    icon: (
      <svg className="w-[18px] h-[18px]" fill="none" stroke="currentColor" strokeWidth={1.8} viewBox="0 0 24 24">
        <path d="M3 10h18M7 15h2m4 0h2M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" />
      </svg>
    ),
  },
  {
    label: "Income",
    href: "/dashboard/income",
    icon: (
      <svg className="w-[18px] h-[18px]" fill="none" stroke="currentColor" strokeWidth={1.8} viewBox="0 0 24 24">
        <rect x="2" y="7" width="20" height="14" rx="2" ry="2" />
        <path d="M16 21V5a2 2 0 00-2-2h-4a2 2 0 00-2 2v16" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    ),
  },
  {
    label: "Expenses",
    href: "/dashboard/expenses",
    icon: (
      <svg className="w-[18px] h-[18px]" fill="none" stroke="currentColor" strokeWidth={1.8} viewBox="0 0 24 24">
        <path d="M4 2v20l2-1 2 1 2-1 2 1 2-1 2 1 2-1 2 1V2l-2 1-2-1-2 1-2-1-2 1-2-1-2 1-2-1z" strokeLinecap="round" strokeLinejoin="round" />
        <path d="M16 8H8m8 4H8m5 4H8" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    ),
  },
  {
    label: "Budget",
    href: "/dashboard/budget",
    icon: (
      <svg className="w-[18px] h-[18px]" fill="none" stroke="currentColor" strokeWidth={1.8} viewBox="0 0 24 24">
        <path d="M9 17v-2m3 2v-4m3 4v-6m2 10H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
      </svg>
    ),
  },
  {
    label: "Investments",
    href: "/dashboard/investments",
    icon: (
      <svg className="w-[18px] h-[18px]" fill="none" stroke="currentColor" strokeWidth={1.8} viewBox="0 0 24 24">
        <path d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    ),
  },
  {
    label: "Tax",
    href: "/dashboard/tax-reports",
    icon: (
      <svg className="w-[18px] h-[18px]" fill="none" stroke="currentColor" strokeWidth={1.8} viewBox="0 0 24 24">
        <path d="M9 7h9m-9 5h9m-9 5h9M5 7h.01M5 12h.01M5 17h.01" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    ),
  },
  {
    label: "Loans",
    href: "/dashboard/liabilities",
    icon: (
      <svg className="w-[18px] h-[18px]" fill="none" stroke="currentColor" strokeWidth={1.8} viewBox="0 0 24 24">
        <path d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
      </svg>
    ),
  },
  {
    label: "Goals",
    href: "/dashboard/goals",
    icon: (
      <svg className="w-[18px] h-[18px]" fill="none" stroke="currentColor" strokeWidth={1.8} viewBox="0 0 24 24">
        <path d="M13 10V3L4 14h7v7l9-11h-7z" />
      </svg>
    ),
  },
  {
    label: "Family",
    href: "/dashboard/family",
    icon: (
      <svg className="w-[18px] h-[18px]" fill="none" stroke="currentColor" strokeWidth={1.8} viewBox="0 0 24 24">
        <path d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z" />
      </svg>
    ),
  },
  {
    label: "Ledger",
    href: "/dashboard/ledger",
    icon: (
      <svg className="w-[18px] h-[18px]" fill="none" stroke="currentColor" strokeWidth={1.8} viewBox="0 0 24 24">
        <path d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4" />
      </svg>
    ),
  },
  {
    label: "Settings",
    href: "/dashboard/settings",
    icon: (
      <svg className="w-[18px] h-[18px]" fill="none" stroke="currentColor" strokeWidth={1.8} viewBox="0 0 24 24">
        <path d="M12 15a3 3 0 100-6 3 3 0 000 6z" />
        <path d="M19.4 15a1.65 1.65 0 00.33 1.82l.06.06a2 2 0 010 2.83 2 2 0 01-2.83 0l-.06-.06a1.65 1.65 0 00-1.82-.33 1.65 1.65 0 00-1 1.51V21a2 2 0 01-4 0v-.09A1.65 1.65 0 009 19.4a1.65 1.65 0 00-1.82.33l-.06.06a2 2 0 01-2.83-2.83l.06-.06A1.65 1.65 0 004.68 15a1.65 1.65 0 00-1.51-1H3a2 2 0 010-4h.09A1.65 1.65 0 004.6 9a1.65 1.65 0 00-.33-1.82l-.06-.06a2 2 0 012.83-2.83l.06.06A1.65 1.65 0 009 4.68a1.65 1.65 0 001-1.51V3a2 2 0 014 0v.09a1.65 1.65 0 001 1.51 1.65 1.65 0 001.82-.33l.06-.06a2 2 0 012.83 2.83l-.06.06A1.65 1.65 0 0019.4 9a1.65 1.65 0 001.51 1H21a2 2 0 010 4h-.09a1.65 1.65 0 00-1.51 1z" />
      </svg>
    ),
  },
];

function NavItem({ label, href, icon, pathname, isCollapsed }: (typeof nav)[0] & { pathname: string; isCollapsed: boolean }) {
  const active = pathname === href || (href !== "/dashboard" && pathname.startsWith(href + "/"));
  return (
    <Link
      href={href}
      prefetch={true}
      aria-label={label}
      title={isCollapsed ? label : undefined}
      className={`relative flex items-center rounded-xl transition-all duration-300 no-underline border ${
        isCollapsed ? "justify-center p-2 w-9 h-9 mx-auto" : "gap-2.5 px-3 py-2 hover:pl-3.5"
      } ${
        active 
          ? "text-amber-200 bg-amber-500/10 border-amber-500/20 font-semibold" 
          : "text-slate-300 border-transparent hover:bg-slate-800/40 hover:text-white group"
      }`}
    >
      {active && (
        <span 
          className="absolute left-0 top-2 bottom-2 w-1 rounded-r-full bg-amber-400"
          aria-hidden="true"
        />
      )}
      <span className={`transition-transform duration-300 ${active ? "text-amber-400 scale-110" : "text-slate-400 group-hover:text-slate-200 group-hover:scale-105"}`} aria-hidden="true">
        {icon}
      </span>
      {!isCollapsed && <span className="font-medium text-xs tracking-wide">{label}</span>}
    </Link>
  );
}

const quickActions = [
  { label: "Expense", href: "/dashboard/expenses?action=new", icon: "🔴", color: "var(--danger)" },
  { label: "Income", href: "/dashboard/income?action=new", icon: "🟢", color: "var(--success)" },
  { label: "Transfer", href: "/dashboard/accounts?action=transfer", icon: "🔄", color: "var(--accent-primary-light)" },
  { label: "Trade", href: "/dashboard/stocks?action=new", icon: "📈", color: "#3b82f6" },
  { label: "FnO", href: "/dashboard/fno?action=new", icon: "📊", color: "#10b981" },
  { label: "Funds", href: "/dashboard/mutual-funds?action=new", icon: "🏦", color: "#a855f7" },
  { label: "Bonds", href: "/dashboard/bonds?action=new", icon: "🔏", color: "#eab308" },
  { label: "Forex", href: "/dashboard/forex?action=new", icon: "💱", color: "#fbbf24" },
  { label: "Liability", href: "/dashboard/liabilities?action=new", icon: "💸", color: "#ec4899" },
  { label: "Alt Asset", href: "/dashboard/alternative-assets?action=new", icon: "🏢", color: "#14b8a6" },
  { label: "Family Send", href: "/dashboard/family?action=send", icon: "👨‍👩‍👧‍👦", color: "#8b5cf6" },
];

const actionModuleMap: Record<string, string> = {
  "Expense": "Expenses",
  "Income": "Income",
  "Trade": "Stocks",
  "FnO": "FnO",
  "Funds": "Mutual Funds",
  "Bonds": "Bonds",
  "Forex": "Forex",
  "Liability": "Liabilities",
  "Alt Asset": "Alt Assets",
  "Family Send": "Family Management",
};

export default function Sidebar() {
  const { data: { profile } } = useFinanceData();
  const router = useRouter();
  const pathname = usePathname();
  const [isMoreOpen, setIsMoreOpen] = useState(false);
  const [isQuickActionOpen, setIsQuickActionOpen] = useState(false);
  const [isCollapsed, setIsCollapsed] = useState(false);
  const [isLogoutOpen, setIsLogoutOpen] = useState(false);
  const quickActionDialogRef = useRef<HTMLDivElement | null>(null);
  const previousFocusRef = useRef<HTMLElement | null>(null);

  useEffect(() => {
    const saved = localStorage.getItem("sidebar_collapsed");
    if (saved === "true") {
      setTimeout(() => setIsCollapsed(true), 0);
    }
  }, []);

  const toggleCollapse = () => {
    const nextVal = !isCollapsed;
    setIsCollapsed(nextVal);
    localStorage.setItem("sidebar_collapsed", String(nextVal));
  };

  const enabledModules = useMemo(() => {
    return getCanonicalEnabledModules(profile?.enabled_modules);
  }, [profile]);

  const { user } = useUser();

  const filteredNav = useMemo(() => {
    const userEmail = (user?.email || "").toLowerCase().trim();
    const isSuperAdminEmail = userEmail === "iamsaran.ai@gmail.com";

    return nav.filter((item) => {
      if (item.label === "Super Admin") {
        return isSuperAdminEmail;
      }

      if (["Dashboard", "Accounts", "Settings"].includes(item.label)) return true;

      const dbLabel: ModuleKey | string =
        item.label === "Income" || item.label === "Expenses"
          ? "Income & Expenses"
          : item.label === "Tax"
          ? "Tax & Reports"
          : item.label === "Assets"
          ? "Alt Assets"
          : item.label === "Loans"
          ? "Liabilities"
          : item.label === "Family"
          ? "Family Management"
          : item.label;

      return enabledModules.includes(dbLabel) || enabledModules.includes(item.label);
    });
  }, [enabledModules, user?.email]);

  useEffect(() => {
    if (!isMoreOpen && !isQuickActionOpen) return;
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => { document.body.style.overflow = previousOverflow; };
  }, [isMoreOpen, isQuickActionOpen]);

  useEffect(() => {
    const hasOverlayOpen = isMoreOpen || isQuickActionOpen;

    if (hasOverlayOpen && !previousFocusRef.current) {
      previousFocusRef.current = document.activeElement as HTMLElement | null;
    }

    if (!hasOverlayOpen && previousFocusRef.current) {
      previousFocusRef.current.focus();
      previousFocusRef.current = null;
    }
  }, [isMoreOpen, isQuickActionOpen]);

  useEffect(() => {
    const onEscape = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return;
      if (isQuickActionOpen) {
        setIsQuickActionOpen(false);
      }
      if (isMoreOpen) {
        setIsMoreOpen(false);
      }
    };

    window.addEventListener("keydown", onEscape);
    return () => window.removeEventListener("keydown", onEscape);
  }, [isMoreOpen, isQuickActionOpen]);

  useEffect(() => {
    if (!isQuickActionOpen || !quickActionDialogRef.current) return;
    const firstFocusable = quickActionDialogRef.current.querySelector<HTMLElement>("a[href],button:not([disabled])");
    firstFocusable?.focus();
  }, [isQuickActionOpen]);

  async function confirmLogout() {
    const supabase = createClient();
    await supabase.auth.signOut();
    router.push("/login");
  }

  function handleLogout() {
    setIsLogoutOpen(true);
  }

  const filteredQuickActions = useMemo(() => {
    return quickActions.filter(action => {
      const mod = actionModuleMap[action.label];
      return !mod || enabledModules.includes(mod);
    });
  }, [enabledModules]);

  const mobileNavLeft = filteredNav.slice(0, 2);
  // #5 — Expenses is the most-used page; prefer it over Ledger in the right slot
  const expensesItem = filteredNav.find(n => n.label === "Expenses");
  const ledgerItem = filteredNav.find(n => n.label === "Ledger");
  const mobileNavRight = expensesItem ? [expensesItem] : ledgerItem ? [ledgerItem] : [];
  const moreNav = filteredNav.filter(n => !mobileNavLeft.includes(n) && !mobileNavRight.includes(n));

  return (
    <>
      <ConfirmDialog
        isOpen={isLogoutOpen}
        onClose={() => setIsLogoutOpen(false)}
        onConfirm={confirmLogout}
        title="Sign Out"
        description="Are you sure you want to securely sign out of your terminal?"
        confirmLabel="Sign Out"
        variant="danger"
      />

      {/* Universal Quick Action Hub */}
      <div className={`md:hidden fixed inset-0 z-[100] bg-black/80 backdrop-blur-md transition-all duration-500 ${isQuickActionOpen ? "opacity-100" : "opacity-0 pointer-events-none"}`} onClick={() => setIsQuickActionOpen(false)} aria-hidden={!isQuickActionOpen}>
        <div id="quick-actions-dialog" role="dialog" aria-modal="true" aria-label="Quick actions" ref={quickActionDialogRef} className={`absolute bottom-[calc(var(--mobile-bottom-nav-height)+0.5rem)] left-4 right-4 max-h-[75vh] overflow-y-auto no-scrollbar grid grid-cols-2 gap-2.5 sm:gap-3 transition-all duration-500 ${isQuickActionOpen ? "translate-y-0 scale-100" : "translate-y-16 scale-90"}`} onClick={e => e.stopPropagation()}>
          {filteredQuickActions.map((action) => (
            <Link key={action.label} href={action.href} prefetch={true} onClick={() => setIsQuickActionOpen(false)} aria-label={`Add new ${action.label}`} className="glass-card-static p-4 flex flex-col items-center justify-center gap-2.5 no-underline transition-all active:scale-95 shadow-lg bg-[--bg-surface] animate-fade-in" style={{ border: `1px solid ${action.color}30` }}>
              <div className="text-2xl filter drop-shadow-[0_4px_10px_rgba(0,0,0,0.1)]" aria-hidden="true">{action.icon}</div>
              <span className="text-[0.5625rem] font-black uppercase tracking-[0.2em]" style={{ color: action.color }}>{action.label}</span>
            </Link>
          ))}
          <button type="button" onClick={() => setIsQuickActionOpen(false)} aria-label="Cancel quick actions" className="col-span-2 glass-card-static py-3 flex items-center justify-center bg-white/5 border-white/10 mt-1 backdrop-blur-md">
            <span className="text-xs font-black uppercase tracking-widest text-[--text-muted]">Cancel</span>
          </button>
        </div>
      </div>

      {/* Desktop Sidebar */}
      <aside className={`hidden md:flex shrink-0 flex-col h-screen sticky top-0 transition-all duration-300 ${isCollapsed ? "w-20" : "w-44"}`} style={{ background: "var(--sidebar-bg)", borderRight: "1px solid var(--sidebar-border)", backdropFilter: "blur(20px) saturate(1.2)", WebkitBackdropFilter: "blur(20px) saturate(1.2)" }}>
        <div className={`px-3.5 pt-4 pb-2 flex items-center ${isCollapsed ? "justify-center" : "justify-between"}`}>
          {!isCollapsed ? (
            <div className="flex items-center gap-3.5">
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img src="/logo.png" alt="arthaX Logo" className="w-13 h-13 rounded-2xl object-cover shadow-[0_0_24px_rgba(56,189,248,0.5)] border border-sky-400/40 shrink-0" />
              <span className="text-3xl font-[950] text-white tracking-tight leading-none">artha<span className="text-sky-400">X</span></span>
            </div>
          ) : (
            /* eslint-disable-next-line @next/next/no-img-element */
            <img src="/logo.png" alt="arthaX Logo" className="w-13 h-13 rounded-2xl object-cover shadow-[0_0_24px_rgba(56,189,248,0.5)] border border-sky-400/40 shrink-0" title="arthaX" />
          )}
          <button 
            type="button" 
            onClick={toggleCollapse} 
            className="p-1 rounded-lg hover:bg-white/5 text-[--text-muted] hover:text-white transition-colors"
            title={isCollapsed ? "Expand Sidebar" : "Collapse Sidebar"}
            aria-label={isCollapsed ? "Expand sidebar" : "Collapse sidebar"}
          >
            {isCollapsed ? (
              <svg className="w-4 h-4" fill="none" stroke="currentColor" strokeWidth={2.5} viewBox="0 0 24 24"><path d="M9 5l7 7-7 7" /></svg>
            ) : (
              <svg className="w-4 h-4" fill="none" stroke="currentColor" strokeWidth={2.5} viewBox="0 0 24 24"><path d="M15 19l-7-7 7-7" /></svg>
            )}
          </button>
        </div>
        <nav className="flex-1 px-2.5 pt-2 space-y-0.5 overflow-y-auto no-scrollbar">
          {!isCollapsed && <p className="px-3 pb-1 text-[0.625rem] font-bold uppercase tracking-[0.2em] text-[--text-muted] opacity-60">Navigation</p>}
          {filteredNav.map((item) => (<NavItem key={item.href} {...item} pathname={pathname} isCollapsed={isCollapsed} />))}
        </nav>
        <div className="px-2.5 py-3 mt-auto pb-4 flex justify-center">
          {!isCollapsed ? (
            <button type="button" onClick={handleLogout} className="flex w-full items-center justify-center gap-2.5 rounded-xl px-3 py-2 text-[0.6875rem] font-black uppercase tracking-widest transition-all bg-rose-500 text-white shadow-lg shadow-rose-500/20 hover:bg-rose-600 hover:shadow-rose-500/30 active:scale-[0.98]">
              <svg className="w-4 h-4" fill="none" stroke="currentColor" strokeWidth={2.5} viewBox="0 0 24 24"><path d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
              Sign Out
            </button>
          ) : (
            <button type="button" onClick={handleLogout} className="p-2.5 rounded-xl bg-rose-500 text-white hover:bg-rose-600 active:scale-95 shadow-lg shadow-rose-500/20 transition-all flex items-center justify-center w-9 h-9" title="Sign Out">
              <svg className="w-4 h-4" fill="none" stroke="currentColor" strokeWidth={2.5} viewBox="0 0 24 24"><path d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
            </button>
          )}
        </div>
      </aside>

      {/* Mobile More Overlay — #6 improved layout, #25 focus trap */}
      <div
        className={`md:hidden fixed inset-0 z-[120] bg-slate-950/80 backdrop-blur-md transition-all duration-500 ease-in-out ${isMoreOpen ? "opacity-100" : "opacity-0 pointer-events-none"}`}
        onClick={() => setIsMoreOpen(false)}
        aria-hidden={!isMoreOpen}
      >
        <div
          id="more-navigation-dialog"
          role="dialog"
          aria-modal="true"
          aria-label="More navigation"
          className={`fixed bottom-0 left-0 right-0 rounded-t-[32px] max-h-[85vh] flex flex-col transition-all duration-500 transform ${isMoreOpen ? "translate-y-0" : "translate-y-full"}`}
          onClick={(e) => e.stopPropagation()}
          style={{ background: "var(--bg-surface)", boxShadow: "0 -20px 60px rgba(15, 23, 42, 0.15)", borderTop: "1px solid var(--border-default)" }}
        >
          {/* Sticky Header with Drag Handle */}
          <div className="pt-5 pb-4 px-5 sticky top-0 z-10" style={{ background: "var(--bg-surface)", borderRadius: "32px 32px 0 0" }}>
            <div className="w-10 h-1 bg-white/20 rounded-full mx-auto mb-4" />
            <p className="text-xs font-semibold text-[--text-muted] px-1">More sections</p>
          </div>

          {/* Scrollable Content */}
          <div className="flex-1 overflow-y-auto no-scrollbar px-5 pb-[calc(env(safe-area-inset-bottom,0px)+6rem)]">
            <div className="flex flex-col gap-1 mb-5">
              {moreNav.map((item, idx) => {
                const active = pathname === item.href || (item.href !== "/dashboard" && pathname.startsWith(item.href + "/"));
                return (
                  <Link
                    key={item.label}
                    href={item.href}
                    prefetch={true}
                    onClick={() => setIsMoreOpen(false)}
                    ref={idx === 0 ? (el) => { if (isMoreOpen && el) el.focus(); } : undefined}
                    className={`flex items-center gap-4 px-4 py-3.5 rounded-2xl no-underline transition-all active:scale-[0.98] ${active ? "bg-[--accent-primary]/10 text-[--accent-primary-light]" : "text-[--text-secondary] hover:bg-white/[0.04]"}`}
                  >
                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${active ? "bg-[--accent-primary]/15 text-[--accent-primary-light]" : "bg-white/[0.05] text-[--text-muted]"}`}>
                      {item.icon}
                    </div>
                    <span className="text-sm font-semibold">{item.label}</span>
                    {active && <div className="ml-auto w-1.5 h-1.5 rounded-full bg-[--accent-primary]" />}
                  </Link>
                );
              })}
            </div>
            <button
              type="button"
              onClick={handleLogout}
              className="w-full flex items-center gap-3 px-5 h-14 rounded-2xl bg-rose-500/10 border border-rose-500/20 text-rose-400 font-bold text-sm active:scale-[0.98] transition-all"
            >
              <svg className="w-4 h-4 shrink-0" fill="none" stroke="currentColor" strokeWidth={2.5} viewBox="0 0 24 24"><path d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
              Sign out
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Bottom Navigation (FAB Optimized) */}
      <nav 
        className="md:hidden fixed left-3 right-3 z-[90] flex h-[68px] items-center justify-between rounded-[28px] border border-[--accent-primary]/10 px-1 transition-transform duration-300 sm:left-4 sm:right-4 sm:h-[72px] sm:rounded-[32px]"
        style={{
          bottom: "max(0.5rem, env(safe-area-inset-bottom, 0px))",
          background: "rgba(21, 25, 34, 0.85)",
          backdropFilter: "blur(20px)",
          WebkitBackdropFilter: "blur(20px)",
          boxShadow: "0 10px 40px rgba(0, 0, 0, 0.4)",
        }}
      >
        {/* Left Side */}
        {mobileNavLeft.map((item) => {
          const active = pathname === item.href || (item.href !== "/dashboard" && pathname.startsWith(item.href + "/"));
          return (
            <Link key={item.label} href={item.href} prefetch={true} className={`flex-1 flex flex-col items-center justify-center gap-1 py-1 transition-all active:scale-90 ${active ? "text-[--accent-primary-light]" : "text-[--text-muted]"}`}>
              <div className={`${active ? "scale-110" : "opacity-70"} transition-all duration-300`}>{item.icon}</div>
              <span className={`text-[10px] sm:text-xs font-semibold leading-none transition-all duration-300 ${active ? "opacity-100 font-bold" : "opacity-70"}`}>{item.label}</span>
            </Link>
          );
        })}

        {/* UNIVERSAL FAB */}
        <div className="flex-1 flex justify-center h-full items-center relative">
           <button 
             type="button"
             onClick={() => setIsQuickActionOpen(!isQuickActionOpen)}
             aria-label={isQuickActionOpen ? "Close quick actions" : "Open quick actions"}
            aria-expanded={isQuickActionOpen}
            aria-controls="quick-actions-dialog"
            className={`w-14 h-14 rounded-full flex items-center justify-center shadow-2xl transition-all duration-500 active:scale-95 absolute -top-4 z-[110] ${isQuickActionOpen ? "bg-rose-500 rotate-45" : "bg-gradient-to-br from-sky-500 to-cyan-400"}`}
            style={{ boxShadow: isQuickActionOpen ? "0 8px 32px rgba(244,63,94,0.5)" : "0 8px 24px rgba(108,92,231,0.4)" }}
           >
             <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" strokeWidth={3} viewBox="0 0 24 24" aria-hidden="true"><path d="M12 4v16m8-8H4" /></svg>
           </button>
        </div>

        {/* Right Side */}
        {mobileNavRight.map((item) => {
          const active = pathname === item.href || (item.href !== "/dashboard" && pathname.startsWith(item.href + "/"));
          return (
            <Link key={item.label} href={item.href} prefetch={true} className={`flex-1 flex flex-col items-center justify-center gap-1 py-1 transition-all active:scale-90 ${active ? "text-[--accent-primary-light]" : "text-[--text-muted]"}`}>
              <div className={`${active ? "scale-110" : "opacity-70"} transition-all duration-300`}>{item.icon}</div>
              <span className={`text-[10px] sm:text-xs font-semibold leading-none transition-all duration-300 ${active ? "opacity-100 font-bold" : "opacity-70"}`}>{item.label}</span>
            </Link>
          );
        })}
        
        <button type="button" onClick={() => setIsMoreOpen(true)} aria-label="Open more navigation" aria-expanded={isMoreOpen} aria-controls="more-navigation-dialog" className={`flex-1 flex flex-col items-center justify-center gap-1 py-1 transition-all active:scale-90 ${isMoreOpen ? "text-[--accent-primary-light]" : "text-[--text-muted]"}`}>
          <div className={`${isMoreOpen ? "scale-110" : "opacity-60"} transition-all duration-300`}><svg className="w-5 h-5" fill="none" stroke="currentColor" strokeWidth={2.5} viewBox="0 0 24 24"><path d="M4 6h16M4 12h16M4 18h16" /></svg></div>
          <span className={`text-[10px] sm:text-xs font-bold leading-none transition-all duration-300 ${isMoreOpen ? "opacity-100" : "opacity-70"}`}>More</span>
        </button>
      </nav>
    </>
  );
}
